private string HashPassword(string password)
{
    // Generate a random salt
    byte[] salt;
    new RNGCryptoServiceProvider().GetBytes(salt = new byte[16]);

    // Create a password hash using PBKDF2
    using (var pbkdf2 = new Rfc2898DeriveBytes(password, salt, 10000, HashAlgorithmName.SHA256))
    {
        byte[] hash = pbkdf2.GetBytes(20); // 20 is the size of the hash

        // Use Convert.ToBase64String directly on the hashBytes
        string base64Hash = Convert.ToBase64String(hash);

        // Combine salt and hash for storage if needed
        byte[] hashBytes = new byte[36]; // 16 for salt + 20 for hash
        Array.Copy(salt, 0, hashBytes, 0, 16);
        Array.Copy(hash, 0, hashBytes, 16, 20);

        return base64Hash;
    }
}

private bool VerifyPassword(string inputPassword, string hashedPassword)
{
    try
    {
        // Debugging: Print hashed password and input password
        Console.WriteLine($"Stored Hashed Password: {hashedPassword}");
        Console.WriteLine($"Input Password: {inputPassword}");

        // Check if the hashed password is a valid Base64 string
        if (!IsValidBase64String(hashedPassword))
        {
            Console.WriteLine("Invalid Base64 String");
            return false;
        }

        // Convert the base64-encoded string back to bytes
        byte[] hashBytes = Convert.FromBase64String(hashedPassword);

        // Debugging: Print hash bytes
        Console.WriteLine($"Decoded Hash Bytes: {BitConverter.ToString(hashBytes)}");

        // Extract the salt and hash from the combined bytes
        byte[] salt = new byte[16];
        Array.Copy(hashBytes, 0, salt, 0, 16);
        byte[] inputHash;
        using (var pbkdf2 = new Rfc2898DeriveBytes(inputPassword, salt, 10000, HashAlgorithmName.SHA256))
        {
            inputHash = pbkdf2.GetBytes(20); // 20 is the size of the hash
        }

        // Debugging: Print input hash bytes
        Console.WriteLine($"Input Hash Bytes: {BitConverter.ToString(inputHash)}");

        // Compare the computed hash with the stored hash
        for (int i = 0; i < 20; i++)
        {
            if (inputHash[i] != hashBytes[i + 16])
            {
                return false;
            }
        }
        return true;
    }
    catch (Exception ex)
    {
        // Handle the exception and print a message
        Console.WriteLine($"Error in VerifyPassword: {ex.Message}");
        return false;
    }
}

private bool IsValidBase64String(string s)
{
    try
    {
        Convert.FromBase64String(s);
        return true;
    }
    catch
    {
        return false;
    }
}

