    col = 1 + Floor[(i - 1)/Length[imgBlocks]];
    str = i - (col - 1)*(Length[imgBlocks]);
    origBlock = imgBlocks[[str]][[col]];
    deltaL = lImgData[[str]][[col]][[1]] - lImgData[[str]][[col]][[2]];
