     l0 = Round[Mean[dotMult0]*2];
     deltaL = l0 - l1;

     If[(s == 1 && deltaL < alpha ) || (s == 0 && deltaL > -alpha ),
      If[s == 1, deltaL = alpha - deltaL, deltaL = -alpha - deltaL];
      deltaV = l*deltaL;
      constArr = ConstantArray[deltaV, {8, 8}]*matrRev;
      block = ImageData[origBlock, "Byte"];
      blockNew = Round[block + constArr];
      newBlockImage = Image[blockNew, "Byte"];
      origBlock = newBlockImage;
      ];
     modifCont[[str]][[col]] = newBlockImage;
     ];
    ];
