请详细解释以下代码:package controller

import (
	"computingDeviceFinanceSvr/com"
	"computingDeviceFinanceSvr/constants"
	"computingDeviceFinanceSvr/model"
	"computingDeviceFinanceSvr/service"
	"computingDeviceFinanceSvr/utility"

	"net/http"
	"github.com/gin-gonic/gin"
)

type BillCtl struct {
}

func NewBillCtl() *BillCtl {
	return &BillCtl{}
}

func (c *BillCtl) BillQuery(ctx *gin.Context) {
	req := model.BillQueryIn{}
	if err := ctx.ShouldBind(&req); err != nil {
		com.Log.Error("param Bind failed err :%v", err)
		utility.RespErrAbort(ctx, http.StatusOK, com.ErrParam)
		return
	}

	// 获取查询用户账号（邮箱）
	email := ctx.Request.Header.Get(constants.RequestHeaderUser)
	if email == "" {
		com.Log.Error("request X-Onething-User is nil")
		utility.RespErrAbort(ctx, http.StatusOK, com.ErrParam)
		return
	}

	role, err := service.GetBillService().GetOperatorRole(email)
	if err != nil {
		utility.RespErrAbort(ctx, http.StatusOK, com.ErrServiceBusy)
		return
	}

	// 查询账单
	data, errBill := service.GetBillService().GetBillInfo(&req, email, role)
	if errBill != nil {
		com.Log.Error("query bill info failed email :%v,req :%v err :%v", email, req, errBill)
		utility.RespErrAbort(ctx, http.StatusOK, com.ErrServiceBusy)
		return
	}

	utility.RespSuccessAbort(ctx, data)
	return
}

