            text/css                                         css;
            text/xml                                         xml;
            image/gif                                        gif;
            image/jpeg                                       jpeg jpg;
            application/javascript                           js;
            application/atom+xml                             atom;
            application/rss+xml                              rss;
            text/mathml                                      mml;
            text/plain                                       txt;
