const fs = require("fs");

let numChanged = 0;
let numUnchanged = 0;

// Read the old code CSV file
const Codes = {};
fs.readFileSync("./imports/itemCodes.csv", "utf-8")
  .split("\n")
  .forEach((line) => {
    const [oldCode, newCode] = line.trim().split(",");
    Codes[oldCode] = newCode;
  });

// Read the price CSV file
const data = [[]];
fs.readFileSync("./imports/afar2015.csv", "utf-8")
  .split("\n")
  .forEach((line, index) => {
    // if (index < 3) {
    //   // Skip header rows
    //   data.push([line.trim()]);
    //   return;
    // }
    line = line.trim();
    if (line === "") {
      return;
    } // Skip empty lines
    data.push(line.split(","));
  });

// Update the codes in the data CSV file
const changedRows = [];
const unchangedRows = [];
for (let row = 4; row < data.length; row++) {
  const oldCode = data[row][1];
  const newCode = Codes[oldCode];
  if (newCode) {
    data[row][1] = newCode;
    changedRows.push(row);
  } else {
    unchangedRows.push(row);
  }
}
console.log("Unchanged row", data[34]);
console.log("Unchanged rows", unchangedRows);

// Write the updated CSV file

const output = data.map((row) => row.join(",")).join("\n");
fs.writeFileSync("./exports/updated_data.csv", output);

// Output changed rows and values
if (changedRows.length === 0) {
  console.log("No codes were updated.");
} else {
  console.log(`Updated codes in rows ${changedRows.join(", ")}.`);
  console.log("New values:");
  changedRows.forEach((row) => {
    console.log(data[row].join(", "));
  });
}
