            rows: List<DataRow>.generate(
              snapshot.data!.length,
              (index) => DataRow(
                cells: [
                  DataCell(Text('${index + 1}')),
                  DataCell(Text('${snapshot.data![index]['userId']}')),
                  DataCell(Text('${snapshot.data![index]['score']}')),
                ],
              ),
            ),
          );
        }
      },
    );
  }
}

