package
{
    import flash.display.Sprite;
    import flash.display.Shape;
    import flash.events.Event;
    import zip.ZIPResourceLoader;
	import zip.ZIPClientLoader;
    import flash.events.ProgressEvent;
	import flash.text.TextField;
    import flash.text.TextFormat;

    public class ProgressBar extends Sprite
    {
        public var progressBar:Shape;
        private var backgroundBar:Shape;
        public var progress:Number;
        private var maxWidth:Number;
        private var maxHeight:Number;
        public var resourceLoader:ZIPResourceLoader;
		public var clientLoader:ZIPClientLoader;
        private var bytesLoaded:Number;
        private var bytesTotal:Number;
		private var direction:int = 1; // Направление анимации (1 - вперед, -1 - назад)
        private var animationSpeed:Number = 0.01; // Скорость анимации прогресс-бара
		private var rectangle:Shape = new Shape();
		public var progressText:TextField;

        public function ProgressBar()
        {
            init();
        }

        public function setClientLoader(clientLoader:ZIPClientLoader):void 
		{
            clientLoader.addEventListener(ProgressEvent.PROGRESS, onProgressUpdate);
        }

        public function setResourceLoader(resourceLoader:ZIPResourceLoader):void 
		{
            resourceLoader.addEventListener(ProgressEvent.PROGRESS, onProgressUpdate);
        }

        public function onProgressUpdate(event:ProgressEvent):void 
		{
            progress = event.bytesLoaded / event.bytesTotal;
            updateProgressBar();
        }

        private function init():void
        {
			clientLoader = new ZIPClientLoader(this);
	        //resourceLoader = new ZIPResourceLoader(this);
            maxWidth = 700;
            maxHeight = 28;
            progress = 0;

            backgroundBar = new Shape();
            backgroundBar.graphics.beginFill(0x014ca3);
			 var cornerRadius:Number = 10;
            backgroundBar.graphics.drawRoundRect(0, 0, maxWidth, maxHeight, cornerRadius);

            backgroundBar.graphics.endFill();

            progressBar = new Shape();
            progressBar.visible = false;

            addChild(backgroundBar);
            addChild(progressBar);

            progressText = new TextField();
            progressText.width = maxWidth;
            progressText.height = maxHeight;
            progressText.text = "Скачивание файлов...";
            var textFormat:TextFormat = new TextFormat("_sans", 18, 0x348aee);
            textFormat.align = "center";
            progressText.y = maxHeight + 10;
            progressText.defaultTextFormat = textFormat;
            addChild(progressText);
            progressText.visible = false;

            addEventListener(Event.ADDED_TO_STAGE, onAddedToStage);
            addEventListener(Event.REMOVED_FROM_STAGE, onRemovedFromStage);
        }

        public function incilizationProgressBar():void
        {
             // Обновление параметров размеров прогресс-бара
            maxWidth = 54;
            maxHeight = 34;
            var cornerRadius:Number = 5;
            var yOffset:Number = -3; // смещение по вертикали на 2 пикселя

            // Создание прямоугольника
            var rectangle:Shape = new Shape();
            rectangle.graphics.beginFill(0x348aee);
            rectangle.graphics.drawRoundRect(0, yOffset, maxWidth, maxHeight, cornerRadius, cornerRadius);
            rectangle.graphics.endFill();

            addChild(rectangle);

           var direction:int = 1; // Направление анимации (1 - вперед, -1 - назад)
           var speed:Number = 7; // Скорость анимации (пиксели за шаг)
           var targetX:Number = 650; // Конечная позиция прямоугольника

           addEventListener(Event.ENTER_FRAME, incilizationAnimateProgressBar);

           function incilizationAnimateProgressBar(event:Event):void
           {
                rectangle.x += direction * speed;

                if (rectangle.x >= targetX || rectangle.x <= 0)
                {
                    direction *= -1; // Переключение направления анимации
                }
           }
        }

        private function onAddedToStage(event:Event):void
        {
            removeEventListener(Event.ADDED_TO_STAGE, onAddedToStage);
            addEventListener(Event.ENTER_FRAME, onUpdate);
        }

        private function onRemovedFromStage(event:Event):void
        {
            removeEventListener(Event.REMOVED_FROM_STAGE, onRemovedFromStage);
            removeEventListener(Event.ENTER_FRAME, onUpdate);
        }

        private function onUpdate(event:Event):void
        {
          //progress += 0.005; // Увеличьте прогресс на 0.01 каждый фрейм
            if (progress > 1) progress = 1; // Убедитесь, что прогресс не превышает 1
            updateProgressBar();
        }

        public function updateProgressBar():void
        {
            progressBar.graphics.clear();
            progressBar.graphics.beginFill(0x348aee);
            var cornerRadius:Number = 3;
            var yOffset:Number = -2; // смещение по вертикали на 2 пикселя
            progressBar.graphics.drawRoundRect(-4, yOffset, maxWidth * progress + 4, maxHeight + 4, cornerRadius);
            progressText.text = "Скачивание файлов...";
            progressBar.graphics.endFill();
        }

        public function setProgress(value:Number, maxValue:Number = 1):void 
		{
            progress = value / maxValue;
            if (progress < 0) 
			{
                progress = 0;
            } 
			else if (progress > 1) 
			{
                progress = 1;
            }
            updateProgressBar();
        }
    }
} как сделать чтобы после ZIPClientLoader выполнялся ZIPResourceLoader

