            rectangle.graphics.beginFill(0x348aee);
            rectangle.graphics.drawRoundRect(0, yOffset, maxWidth, maxHeight, cornerRadius, cornerRadius);
            rectangle.graphics.endFill();

            addChild(rectangle);

           var direction:int = 1; // Направление анимации (1 - вперед, -1 - назад)
           var speed:Number = 7; // Скорость анимации (пиксели за шаг)
           var targetX:Number = 650; // Конечная позиция прямоугольника

           addEventListener(Event.ENTER_FRAME, incilizationAnimateProgressBar);

           function incilizationAnimateProgressBar(event:Event):void
           {
                rectangle.x += direction * speed;

                if (rectangle.x >= targetX || rectangle.x <= 0)
                {
                    direction *= -1; // Переключение направления анимации
                }
           }
        }

        private function onAddedToStage(event:Event):void
        {
            removeEventListener(Event.ADDED_TO_STAGE, onAddedToStage);
            addEventListener(Event.ENTER_FRAME, onUpdate);
        }

        private function onRemovedFromStage(event:Event):void
        {
            removeEventListener(Event.REMOVED_FROM_STAGE, onRemovedFromStage);
            removeEventListener(Event.ENTER_FRAME, onUpdate);
        }

        private function onUpdate(event:Event):void
        {
          //progress += 0.005; // Увеличьте прогресс на 0.01 каждый фрейм
            if (progress > 1) progress = 1; // Убедитесь, что прогресс не превышает 1
            updateProgressBar();
        }

        public function updateProgressBar():void
        {
            progressBar.graphics.clear();
            progressBar.graphics.beginFill(0x348aee);
            var cornerRadius:Number = 3;
            var yOffset:Number = -2; // смещение по вертикали на 2 пикселя
            progressBar.graphics.drawRoundRect(-4, yOffset, maxWidth * progress + 4, maxHeight + 4, cornerRadius);
            progressText.text = "Скачивание файлов...";
            progressBar.graphics.endFill();
        }

        public function setProgress(value:Number, maxValue:Number = 1):void 
		{
            progress = value / maxValue;
            if (progress < 0) 
			{
                progress = 0;
            } 
			else if (progress > 1) 
			{
                progress = 1;
            }
            updateProgressBar();
        }
    }
