    private boolean checkCard2CardLimit(Long operationId, OperationType type, String pan, String pan2, String url, BigDecimal amount) {
        FraudCheckRequest fraudCheckRequest = new FraudCheckRequest();
        fraudCheckRequest.setOperationId(operationId);
        fraudCheckRequest.setOperationType(type.name());
        fraudCheckRequest.setPan(pan);
        fraudCheckRequest.setPan2(pan2);
        fraudCheckRequest.setAmount(amount);
        try {
            RequestContent requestContent = requestFraudMonitoring(fraudCheckRequest, url);
            if (requestContent.responseCode == 200) {
                return Boolean.parseBoolean(requestContent.content);
            }
        } catch (Exception e) {
            LOGGER.error("Внешний микросервис недоступен", e);
        }
        // Если микросервис недоступен, то операцию запрещаем
        return false;
    }


    private RequestContent requestFraudMonitoring(FraudCheckRequest fraudCheckRequest, String urlOperation) throws IOException {
        String url = srcRest + urlOperation;
        try (CloseableHttpClient httpClient = HttpClientBuilder.create().build()) {
            HttpPost httpPost = new HttpPost(url);
            httpPost.setHeader("Authorization", authorizationHeaderValue);
            httpPost.setHeader("Content-type", "application/json");
            StringEntity postingString = new StringEntity(new Gson().toJson(fraudCheckRequest), "UTF-8");
            httpPost.setEntity(postingString);

            HttpResponse response = httpClient.execute(httpPost);
            int responseCode = response.getStatusLine().getStatusCode();
            String content = IOUtils.toString(response.getEntity().getContent());
            LOGGER.info("[requestFraudMonitoring] responseCode = " + responseCode);
            LOGGER.info("[requestFraudMonitoring] content = " + content);
            return new RequestContent(responseCode, content);
        }
    }

    private static final class RequestContent {
        private final Integer responseCode;
        private final String content;

        public RequestContent(Integer responseCode, String content) {
            this.responseCode = responseCode;
            this.content = content;
        }
    }

