	    if (IsEqualGUID(rguidCompartment,GUID_COMPARTMENT_KEYBOARD_OPENCLOSE))
	    {//update input mode flags
		    BOOL bOpen=_IsKeyboardOpen();
		    if(!bOpen)
		    {
			    if(_IsCompositing())
			    {
