#include <Trade\Trade.mqh>
input int MagicNumber = 10001;
input double Lots = 0.1;
input int StartHour = 0; // ساعت شروع معاملات
input int EndHour = 24; // ساعت پایان معاملات
// اینپوت‌های بولین برای روزهای هفته
input bool TradeOnSunday = true;
input bool TradeOnMonday = true;
input bool TradeOnTuesday = true;
input bool TradeOnWednesday = true;
input bool TradeOnThursday = true;
input bool TradeOnFriday = false;
input bool TradeOnSaturday = false;

int LastCandleIndex = -1; // شماره آخرین کندلی که در آن معامله‌ای باز شده است

void OnTick() {
    CTrade trade;
    trade.SetExpertMagicNumber(MagicNumber);
    double Ask = SymbolInfoDouble(_Symbol, SYMBOL_ASK);
    double Bid = SymbolInfoDouble(_Symbol, SYMBOL_BID);

    MqlDateTime TimeNow;
    TimeCurrent(TimeNow);

    // بررسی روز هفته برای معامله
    if (!IsTradeDay(TimeNow.day_of_week) || TimeNow.hour < StartHour || TimeNow.hour > EndHour)
        return; // اگر امروز روز معاملاتی نیست یا خارج از بازه زمانی است، از ادامه کد صرف نظر می‌کنیم

    int CurrentCandleIndex = iBars(_Symbol, PERIOD_CURRENT);

    double PreviousHigh = iHigh(_Symbol, PERIOD_CURRENT, 1);
    double PreviousLow = iLow(_Symbol, PERIOD_CURRENT, 1);
    double CandleSize = PreviousHigh - PreviousLow;

    if (CurrentCandleIndex != LastCandleIndex && iHigh(_Symbol, PERIOD_CURRENT, 0) > PreviousHigh) {
        double TheStopLoss = PreviousLow - 10 * _Point;
        double TheTakeProfit = Ask + CandleSize;
        trade.PositionOpen(_Symbol, ORDER_TYPE_BUY, Lots, Ask, TheStopLoss, TheTakeProfit);

        LastCandleIndex = CurrentCandleIndex;
    }
}

// تابع بررسی روز معاملاتی بر اساس اینپوت‌ها
bool IsTradeDay(int dayOfWeek) {
    switch(dayOfWeek) {
        case 0: return TradeOnSunday;
        case 1: return TradeOnMonday;
        case 2: return TradeOnTuesday;
        case 3: return TradeOnWednesday;
        case 4: return TradeOnThursday;
        case 5: return TradeOnFriday;
        case 6: return TradeOnSaturday;
        default: return false;
    }
}


