export interface ProfitChartWidgetType {
  [key: string]: string | number;
}

interface CumulativeProfitChartProps {
  data: ProfitChartWidgetType;
}

const CumulativeProfitChart = ({data}: CumulativeProfitChartProps) => {
  const [profitData, setProfitData] = useState<ProfitChartWidgetType[]>([]);
  const darkTheme = useTheme().palette.mode === "dark";

  useEffect(() => {
    if (data.length === 0) {
      setProfitData([]);
    } else {
      setProfitData(parseProfitData(data));
    }
  }, [data]);

  if(Object.entries(data).length === 0) {
    return <></>;
  }

  return <>
    <Box p={1} mt={-2.5} height="calc(100% - 110px)">
      <ResponsiveContainer
        minHeight={"100%"}
        height="100%"
        width="100%"
      >
        <LineChart margin={{
          top: 20,
          right: 0,
          left: 3,
          bottom: -5,
        }} width={500} data={profitData}>
          <CartesianGrid strokeDasharray="3 3" stroke={darkTheme ? "#5c5a57" : "#ccc"} />
          <XAxis
            dataKey="date"
            axisLine={false}
            tickLine={false}

          />
          <YAxis
            orientation="right"
            axisLine={false}
            tickLine={false}
    />
          <Tooltip content={<CustomTooltip />} />
          <Line
            type="linear"
            dataKey="profit"
            stroke="#006943"
            strokeWidth={3}
            dot={false}
          />
        </LineChart>
      </ResponsiveContainer>
    </Box>
  </>;
};

const parseProfitData = (profitData: Record<string, string | number>): ProfitChartWidgetType[] => {
  const result: ProfitChartWidgetType[] = [];

  const dates: string[] = Object.keys(profitData).sort((a, b) => dayjs(a).isBefore(dayjs(b)) ? -1 : 1);
  let prevDate = dates[0];

  for (const date of dates) {
    if (Object.hasOwnProperty.call(profitData, date)) {
      const currentDate = dayjs(date);
      const prevDateValue = profitData[prevDate];
      const currentDateValue = typeof profitData[date] === "number" ? profitData[date] : parseFloat(profitData[date] as string);

      if (currentDate.diff(prevDate, "day") > 1) {
        const missingDates = findMissingDates(prevDate, currentDate);

        for (const missingDate of missingDates) {
          result.push({
            date: missingDate,
            profit: prevDateValue,
          });
        }
      }

      result.push({
        date: date,
        profit: currentDateValue,
      });

      prevDate = date;
    }
  }

  return result;
};

const findMissingDates = (prevDate: string, currentDate: dayjs.ConfigType): string[] => {
  const missingDates: string[] = [];
  let tempDate = dayjs(prevDate).add(1, "day");

  while (tempDate.isBefore(currentDate, "day")) {
    missingDates.push(tempDate.format("YYYY-MM-DD"));
    tempDate = tempDate.add(1, "day");
  }

  return missingDates;
};

