вводятся времена работы касс. Нужно вывести сколько секунд все кассы работают одновременно. Если время начала больше времени окончания, значит произошла смена суток. Если время начала равно времени окончания, значит касса работает круглосуточно

#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>

#define int long long

using namespace std;

struct event {
    int x, type;
};

signed main() {
    ios::sync_with_stdio(0);
    cin.tie(nullptr);
    cout.tie(nullptr);

    int n; cin >> n;
    vector<pair<int, int>> segments;
    int flag = 0;

    for (int i = 0; i < n; i++) {
        int hh1, hh2, mm1, mm2, ss1, ss2;
        cin >> hh1 >> mm1 >> ss1 >> hh2 >> mm2 >> ss2;
        int t1 = hh1 * 3600 + mm1 * 60 + ss1;
        int t2 = hh2 * 3600 + mm2 * 60 + ss2;
        if (t2 < t1) {
            segments.push_back({ t1, 24 * 3600 });
            segments.push_back({ 0, t2 });
            flag++;
        }
        else if (t1 != t2) {
            segments.push_back({ t1, t2 });
            flag++;
        }
    }

    vector<event> events;

    n = segments.size();

    for (int i = 0; i < n; i++) {
        events.push_back({ segments[i].first, 1 });
        events.push_back({ segments[i].second, -1 });
    }

    sort(events.begin(), events.end(), [](event a, event b) {
        return a.x < b.x || (a.x == b.x && a.type < b.type);
        });

    int cnt = 0;
    int ans = 0;
    int temp;


    for (auto e : events) {
        if (e.type == 1) {
            temp = e.x;
            cnt++;
        }
        else {
            if (cnt == flag) {
                ans += e.x - temp;
            }
            cnt--;
        }
    }

    cout << ans % (24 * 3600);

    return 0;
}

