/* Установка соединения с бд */
$link = mysqli_connect("localhost", "root", "", "интернет магазин одежды");
/* Проверка соединения с бд */
if (mysqli_connect_errno()) {
printf("Не удалось подключиться: %s\n", mysqli_connect_error());
exit();
}
/* SQL запрос на выборку данных из таблицы zriteli*/
$result = mysqli_query($link, "SELECT * FROM catalog LIMIT 100");
$products = mysqli_fetch_all($result, MYSQLI_ASSOC); // Преобразование результата запроса в ассоциативный массив
/* Завершение соединения с БД */
mysqli_close($link);
?>

</section>
<div class="container">
<header class="header">
<h4 class="title">Фильтр товаров</h4>
<small class="subtitle">Поиск по названию</small>
<input type="text" id="filter" placeholder="Search">
</header>
<ul id="result" class="user-list">
<li>
<h3>Loading...</h3>
</li>
</ul>
</div>

<footer>
2023 © Clothes Store
</footer>
<script>
const products = <?php echo json_encode($products); ?>; // Преобразование массива товаров в JSON
const result = document.getElementById('result');
const filter = document.getElementById('filter');
const listItems = [];

// Заполняем список результатов при загрузке страницы
fillResult(products);

// Слушаем изменения в поле поиска и фильтруем данные
filter.addEventListener('input', (e) => filterData(e.target.value));

function fillResult(data) {
result.innerHTML = ''; // Очищаем результат

data.forEach(product => {
const li = document.createElement('li');
listItems.push(li);
li.innerHTML = `
<img src="data:image/jpeg;base64,${product.image}" alt="${product.Nazvanie}">
<div class="product-info">
<h4>${product.Nazvanie}</h4>
<p>${product.Brend}</p>
<p>${product.Price} руб.</p>
</div>
`;
result.appendChild(li);
});
}

function filterData(searchTerm) {
listItems.forEach(item => {
const productName = item.querySelector('h4').innerText;
if (productName.toLowerCase().includes(searchTerm.toLowerCase())) {
item.classList.remove('hide');
} else {
item.classList.add('hide');
}
});
}

