#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// 学生结构体
struct Student {
    int id;
    char name[50];
    int age;
    struct Student* next;
};

// 全局变量，链表头指针
struct Student* head = NULL;

// 添加学生信息
void addStudent() {
    struct Student* newStudent = (struct Student*)malloc(sizeof(struct Student));
    newStudent->next = NULL;

    printf("请输入学生学号：");
    scanf("%d", &(newStudent->id));

    printf("请输入学生姓名：");
    scanf("%s", newStudent->name);

    printf("请输入学生年龄：");
    scanf("%d", &(newStudent->age));

    if (head == NULL) {
        head = newStudent;
        return;
    }

    struct Student* curr = head;
    while (curr->next != NULL) {
        curr = curr->next;
    }

    curr->next = newStudent;
}

// 删除学生信息
void deleteStudent() {
    if (head == NULL) {
        printf("学生信息为空！\n");
        return;
    }

    int studentId;
    printf("请输入要删除的学生学号：");
    scanf("%d", &studentId);

    struct Student* curr = head;
    struct Student* prev = NULL;

    while (curr != NULL) {
        if (curr->id == studentId) {
            if (prev == NULL) {
                head = curr->next;
            } else {
                prev->next = curr->next;
            }
            free(curr);
            printf("删除成功！\n");
            return;
        }
        prev = curr;
        curr = curr->next;
    }

    printf("未找到学生信息！\n");
}

// 修改学生信息
void modifyStudent() {
    if (head == NULL) {
        printf("学生信息为空！\n");
        return;
    }

    int studentId;
    printf("请输入要修改的学生学号：");
    scanf("%d", &studentId);

    struct Student* curr = head;
    while (curr != NULL) {
        if (curr->id == studentId) {
            printf("请输入学生新姓名：");
            scanf("%s", curr->name);

            printf("请输入学生新年龄：");
            scanf("%d", &(curr->age));

            printf("修改成功！\n");
            return;
        }
        curr = curr->next;
    }

    printf("未找到学生信息！\n");
}

// 查询学生信息
void queryStudent() {
    if (head == NULL) {
        printf("学生信息为空！\n");
        return;
    }

    printf("查询结果如下：\n");
    struct Student* curr = head;
    while (curr != NULL) {
        printf("学生学号：%d， 姓名：%s， 年龄：%d\n", curr->id, curr->name, curr->age);
        curr = curr->next;
    }
}

int main() {
    int choice;

    while (1) {
        printf("\n欢迎使用学生信息查询系统！\n");
        printf("1. 添加学生信息\n");
        printf("2. 删除学生信息\n");
        printf("3. 修改学生信息\n");
        printf("4. 查询学生信息\n");
        printf("5. 退出\n");
        printf("请输入您的选择：");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                addStudent();
                break;
            case 2:
                deleteStudent();
                break;
            case 3:
                modifyStudent();
                break;
            case 4:
                queryStudent();
                break;
            case 5:
                exit(0);
                break;
            default:
                printf("无效的选择！\n");
                break;
        }
    }

    return 0;
}代码详细解释

