using namespace std;

template<typename T>
struct LinkNode//单链表结点类型
{
	T data;
	LinkNode<T>*next;
	LinkNode():next(NULL){}
	LinkNode(T d):data(d),next(NULL){}
};
template <typename T>
class LinkList{


	public:

		LinkNode<T> *head;
		LinkList():head(NULL){}
		~LinkList() { // 析构函数
        if (head) {
            LinkNode<T>* v = head->next;
            while (v != head) {
                LinkNode<T>* temp = v;
                v = v->next;
                delete temp;
            }
            delete head;
        }
    }


		   void DispList() { // 输出链表元素
        if (head) {
            LinkNode<T>* v = head;
            do {
